#include <stdio.h>

int main(void)
{
    int cans = 19;
    int used = 6;
    int batches = 2;
    int days = 4;
    int reserve = (cans - used) * batches;
    double pace = (double)cans / days;
    printf("%d %.2f\n", reserve, pace);
    return 0;
}

